int v[100005], tmp[100005];
void mergeSort(int st, int dr) {
    if (st >= dr) return;
    int m = (st + dr) / 2;
    mergeSort(st, m);
    mergeSort(m + 1, dr);
    int i = st, j = m + 1, k = st;
    while (i <= m && j <= dr) {
        if (v[i] <= v[j]) tmp[k++] = v[i++];
        else tmp[k++] = v[j++];
    }
    while (i <= m) tmp[k++] = v[i++];
    while (j <= dr) tmp[k++] = v[j++];
    for (k = st; k <= dr; k++) v[k] = tmp[k];
}
int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> v[i];
    mergeSort(0, n - 1);
    for (int i = 0; i < n; i++) cout << v[i] << " ";
    return 0;
}

