#include <iostream>
using namespace std;

const int N = 100001;
int f[N], m[N];
bool areF[N], areM[N];

int M(int n);

int F(int n) {
    if (n == 0) return 1;
    if (!areF[n]) {
        f[n] = n - M(F(n - 1));
        areF[n] = true;
    }
    return f[n];
}

int M(int n) {
    if (n == 0) return 0;
    if (!areM[n]) {
        m[n] = n - F(M(n - 1));
        areM[n] = true;
    }
    return m[n];
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i <= n; i++) {  // de jos în sus, ca stiva să nu crească prea mult
        F(i);
        M(i);
    }
    cout << F(n) << " " << M(n) << "\n";
    return 0;
}

