#include <iostream>
using namespace std;

int m, n;
char t[101][101];

void sterge(int i, int j) {
    if (i < 0 || i >= m || j < 0 || j >= n || t[i][j] != '@') return;
    t[i][j] = '*';  // marcat: nu mai e numărat a doua oară
    for (int di = -1; di <= 1; di++)
        for (int dj = -1; dj <= 1; dj++)
            if (di != 0 || dj != 0) sterge(i + di, j + dj);
}

