#include <iostream>
#include <string>
using namespace std;

string s;
int p = 0;

long long expresie();

long long factor() {
    if (s[p] == '(') {
        p++;              // '('
        long long v = expresie();
        p++;              // ')'
        return v;
    }
    long long v = 0;
    while (p < (int)s.size() && s[p] >= '0' && s[p] <= '9') {
        v = v * 10 + (s[p] - '0');
        p++;
    }
    return v;
}

long long termen() {
    long long v = factor();
    while (p < (int)s.size() && (s[p] == '*' || s[p] == '/')) {
        char op = s[p++];
        long long w = factor();
        if (op == '*') v *= w;
        else v /= w;
    }
    return v;
}

long long expresie() {
    long long v = termen();
    while (p < (int)s.size() && (s[p] == '+' || s[p] == '-')) {
        char op = s[p++];
        long long w = termen();
        if (op == '+') v += w;
        else v -= w;
    }
    return v;
}

int main() {
    cin >> s;
    cout << expresie() << "\n";
    return 0;
}

