#include <fstream>
#include <vector>
#include <queue>
#include <array>
using namespace std;
ifstream fin("nestemate.in");
ofstream fout("nestemate.out");
const int VMAX = 500000;
vector<int> cu[VMAX + 1]; // cu[v] = nestematele care au valoarea v
bool folosita[VMAX + 1];
int main() {
    int t;
    fin >> t;
    while (t--) {
        int n, a, b;
        fin >> n >> a >> b;
        vector<array<int, 3>> p(n + 1);
        for (int i = 1; i <= n; i++)
            for (int k = 0; k < 3; k++) {
                fin >> p[i][k];
                cu[p[i][k]].push_back(i);
            }
        // BFS pe nestemate; fiecare valoare se „consumă” o singură dată
        vector<int> d(n + 1, -1);
        queue<int> q;
        d[a] = 0;
        q.push(a);
        while (!q.empty() && d[b] == -1) {
            int x = q.front();
            q.pop();
            for (int k = 0; k < 3; k++) {
                int v = p[x][k];
                if (folosita[v]) continue;
                folosita[v] = true;
                for (int y : cu[v])
                    if (d[y] == -1) {
                        d[y] = d[x] + 1;
                        q.push(y);
                    }
            }
        }
        fout << d[b] << "\n";
        for (int i = 1; i <= n; i++)
            for (int k = 0; k < 3; k++) {
                cu[p[i][k]].clear();
                folosita[p[i][k]] = false;
            }
    }
    return 0;
}

