using namespace std;
long long A[200000], B[200000];
int k = 0;
void generatoare(int n) {
    // a < b: a * b = n
    for (long long a = 2; a * a < n; a = a + 2)
        if (n % a == 0) { A[k] = a; B[k] = n / a; k++; }
    // a >= b: b <= sqrt(n); a * b + a / b crește cu a
    for (long long b = 1; b * b <= n; b++) {
        long long st = b, dr = n / b;
        while (st < dr) {
            long long m = (st + dr) / 2;
            if (m * b + m / b < n) st = m + 1;
            else dr = m;
        }
        if (st * b + st / b == n && st % 2 == 0 && st >= b) { A[k] = st; B[k] = b; k++; }
    }
    if (k == 0) { cout << "nu exista"; return; }
    for (int i = 0; i < k; i++)
        for (int j = i + 1; j < k; j++)
            if (A[j] < A[i]) { swap(A[i], A[j]); swap(B[i], B[j]); }
    for (int i = 0; i < k; i++) cout << A[i] << "-" << B[i] << " ";
}
int main() {
    int n;
    cin >> n;
    generatoare(n);
    return 0;
}

