#include <iostream>
using namespace std;
int main() {
    long long n, a, b, c;
    cin >> n >> a >> b >> c;
    if (n == 1) { cout << a; return 0; }
    if (n == 2) { cout << b << " " << a; return 0; }
    // a, b, c = f[i-2], f[i-1], f[i]
    for (long long i = 4; i <= n; i++) {
        long long d = c + b - a;
        a = b; b = c; c = d;
    }
    cout << c << " " << b << " " << a;
    for (long long i = n - 3; i >= 1; i--) {
        long long d = b + a - c; // f[i] = f[i+2] + f[i+1] - f[i+3]
        c = b; b = a; a = d;
        cout << " " << a;
    }
    return 0;
}

